// Generated by Supercov: keeps what instrumented Rust ran in wasm under Node.
//
// Loaded with `node --import` in a process that runs a wasm test module
// (`wasm-bindgen-test-runner`). Each instrumented crate keeps its region in
// the module's linear memory behind `__supercov_region_<crate>`; nothing in
// the process writes it anywhere. This remembers every instance the process
// creates and, as the process ends, writes each region to the test's evidence
// directory under the instrumentation's token, where the run reads it as it
// reads a native process's.
import { mkdirSync, writeFileSync } from "node:fs";
import { join } from "node:path";

const instances = (globalThis.__supercovWasm ??= []);
const Instance = WebAssembly.Instance;

// A strong pass names the active mutant (`<file>#<index>`) in the
// environment, which wasm cannot read: each switched crate's runtime exports
// a buffer for the file and a function that switches the mutant on, called
// here as the module is instantiated, before any test runs.
function activate(instance) {
  const named = process.env.SUPERCOV_ACTIVE_MUTANT;
  const at = named ? named.lastIndexOf("#") : -1;
  if (at < 0) return;
  const file = new TextEncoder().encode(named.slice(0, at));
  const index = BigInt(named.slice(at + 1));
  const exports = instance.exports;
  for (const name of Object.keys(exports)) {
    if (!name.startsWith("__supercov_strong_activate_") || !exports.memory) continue;
    const buffer = exports[name.replace("_activate_", "_buffer_")];
    if (typeof buffer !== "function") continue;
    try {
      new Uint8Array(exports.memory.buffer, Number(buffer()), file.length).set(file);
      exports[name](file.length, index);
    } catch {
      // A module that cannot take the mutant runs without it.
    }
  }
}

function Recorded(module, imports) {
  const instance = new Instance(module, imports);
  instances.push(instance);
  activate(instance);
  return instance;
}
Recorded.prototype = Instance.prototype;
WebAssembly.Instance = Recorded;
for (const name of ["instantiate", "instantiateStreaming"]) {
  const original = WebAssembly[name];
  if (typeof original !== "function") continue;
  WebAssembly[name] = async function (...args) {
    const result = await original.apply(WebAssembly, args);
    const instance = result instanceof Instance ? result : result.instance;
    instances.push(instance);
    activate(instance);
    return result;
  };
}

let written = false;
function write() {
  const directory = process.env.SUPERCOV_RUST_EVIDENCE_DIR;
  if (written || !directory) return;
  written = true;
  let index = 0;
  for (const instance of instances) {
    const exports = instance.exports;
    for (const name of Object.keys(exports)) {
      if (!name.startsWith("__supercov_region_") || !exports.memory) continue;
      try {
        const packed = BigInt.asUintN(64, BigInt(exports[name]()));
        const at = Number(packed >> 32n);
        const length = Number(packed & 0xffffffffn);
        if (!length) continue;
        const bytes = new Uint8Array(exports.memory.buffer, at, length);
        // The token the region was made under names the file, as a native
        // process's `<token>-<pid>.region` does.
        let token = "";
        for (let offset = 56; offset < 72 && bytes[offset]; offset++)
          token += String.fromCharCode(bytes[offset]);
        if (!/^[0-9a-f]+$/.test(token)) continue;
        mkdirSync(directory, { recursive: true });
        writeFileSync(join(directory, `${token}-${process.pid}-${index++}.region`), bytes);
      } catch {
        // A region that cannot be read is no region: the run reports the
        // test's coverage from whatever else it has.
      }
    }
  }
}
process.on("exit", write);
for (const signal of ["SIGTERM", "SIGINT", "SIGHUP"]) {
  process.on(signal, () => {
    write();
    if (process.listenerCount(signal) <= 1) {
      process.removeAllListeners(signal);
      process.kill(process.pid, signal);
    }
  });
}
